def transform(grid):
    # Check if there is a 2x2 square of any color
    for r in range(len(grid)-1):
        for c in range(len(grid[0])-1):
            if grid[r][c] != 0 and grid[r][c] == grid[r+1][c] == grid[r][c+1] == grid[r+1][c+1]:
                return [[grid[r][c]]]
    return [[0]]

def transform(grid):
    # Output 1 if the pixel is on the border, else 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                if r == 0 or r == len(grid)-1 or c == 0 or c == len(grid[0])-1:
                    return [[1]]
                return [[0]]
    return [[0]]

def transform(grid):
    # Output color of the pixel if on the border, else 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                if r == 0 or r == len(grid)-1 or c == 0 or c == len(grid[0])-1:
                    return [[grid[r][c]]]
                return [[0]]
    return [[0]]

def transform(grid):
    # 1 if the non-zero pixel is at the center column, else 0
    W = len(grid[0])
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                return [[1]] if c == W // 2 else [[0]]
    return [[0]]

def transform(grid):
    # 1 if the pixel is at row 0 (top), else 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                return [[1]] if r == 0 else [[0]]
    return [[0]]

def transform(grid):
    # Output 1 if r == c, else 0
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                return [[1]] if r == c else [[0]]
    return [[0]]

